#!/usr/bin/env python3
"""Evaluate verified capability-frontier routing against global static maps."""

from __future__ import annotations

# --- github publish layout (auto-generated by sync_github_publish.py) ---
import sys
from pathlib import Path as _Path
_GITHUB_ROOT = _Path(__file__).resolve().parents[1]
_BG = _GITHUB_ROOT / "BoundaryGuard"
_EXP = _GITHUB_ROOT / "exp"
for _p in (_BG, _EXP):
    _s = str(_p)
    if _s not in sys.path:
        sys.path.insert(0, _s)
DATA = _GITHUB_ROOT.joinpath("data")
EXP = _EXP
ROOT = _GITHUB_ROOT
# --- end header ---

import json
import statistics
from pathlib import Path


def valid(row: dict) -> bool:
    return row["outcome"] == "ok" and row["semantic_match"]


def p95(values: list[float]) -> float:
    return sorted(values)[max(0, round(0.95 * len(values))-1)]


def main() -> None:
    rows = [json.loads(line) for line in Path("data/provider_frontier_probe.jsonl").read_text().splitlines()]
    result = {"provenance": "live natural RPC responses; routing evaluation is offline replay", "methods": {}}
    for method in sorted({r["method"] for r in rows}):
        table = {}
        for row in (r for r in rows if r["method"] == method):
            table.setdefault(row["block"], {})[row["provider"]] = row
        blocks = sorted(b for b, providers in table.items() if set(providers) == {"flashbots", "zeroxrpc"})
        flash_profile = [valid(table[b]["flashbots"]) for b in blocks]
        transitions = sum(a != b for a, b in zip(flash_profile, flash_profile[1:]))
        first_good = next((i for i, value in enumerate(flash_profile) if value), len(blocks))
        monotone = all(not value for value in flash_profile[:first_good]) and all(flash_profile[first_good:])
        cutoff = blocks[first_good] if first_good < len(blocks) else None
        # Simulate binary probing of the ordered known-message corpus.
        lo, hi, probes = 0, len(blocks), []
        while lo < hi:
            mid = (lo + hi) // 2
            probes.append(blocks[mid])
            if flash_profile[mid]: hi = mid
            else: lo = mid + 1
        routes = {
            "static_zeroxrpc": [table[b]["zeroxrpc"] for b in blocks],
            "static_flashbots": [table[b]["flashbots"] for b in blocks],
            "verified_frontier": [table[b]["flashbots"] if cutoff is not None and b >= cutoff
                                  else table[b]["zeroxrpc"] for b in blocks],
        }
        metrics = {}
        for name, chosen in routes.items():
            successful = [r for r in chosen if valid(r)]
            latencies = [r["latency_ms"] for r in successful]
            metrics[name] = {"delivered": len(successful), "queries": len(chosen),
                             "delivery_rate": len(successful)/len(chosen),
                             "mean_success_latency_ms": statistics.mean(latencies) if latencies else None,
                             "p95_success_latency_ms": p95(latencies) if latencies else None,
                             "sla_1300ms_rate": sum(valid(r) and r["latency_ms"] <= 1300 for r in chosen)/len(chosen)}
        static = metrics["static_zeroxrpc"]["mean_success_latency_ms"]
        frontier = metrics["verified_frontier"]["mean_success_latency_ms"]
        result["methods"][method] = {"samples": len(blocks), "flashbots_profile": flash_profile,
            "profile_transitions": transitions, "monotone_frontier": monotone, "cutoff_block": cutoff,
            "binary_probe_blocks": probes, "binary_probe_count": len(probes), "metrics": metrics,
            "frontier_latency_reduction_vs_reliable_static_pct": (static-frontier)/static*100}
    Path("data/provider_frontier_eval.json").write_text(json.dumps(result, indent=2, sort_keys=True)+"\n")
    print(json.dumps(result, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()
